package com.example.starter.consent;

/**
 * 旧代载荷清除任务状态：PENDING 待清除；DONE 已完成（本代无未清项）。
 * 只允许从 PENDING 变为 DONE。
 */
public enum ErasureTaskStatus {
    PENDING,
    DONE
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 清除执行请求：对指定代次的清除任务执行一批物理清除（最多 5 条，按 recordKey 字典序）。
 * 仅本地角色 ERASER 可调用；同一 requestId 相同参数重放返回首次的无载荷计数。
 *
 * @param requestId  幂等请求标识，同一 requestId 相同参数重试返回首次结果
 * @param subjectKey 主体标识（合成字符串）
 * @param purpose    用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch      待清除的授权代次，从 1 开始
 */
public record ErasureExecuteRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull Purpose purpose,
        @NotNull @Min(1) Integer epoch) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.ErasureTaskStatus;
import com.example.starter.consent.Purpose;

/**
 * 清除任务进度响应：只含计数与状态等元数据，不包含任何记录载荷。
 *
 * @param subjectKey     主体标识（合成字符串）
 * @param purpose        用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch          清除任务所属授权代次
 * @param status         状态：PENDING 待清除 / DONE 已完成
 * @param erasedCount    累计已清除载荷条数（仅统计本代，不跨代）
 * @param remainingCount 本代剩余未清除条数
 */
public record ErasureTaskResponse(String subjectKey, Purpose purpose, int epoch,
                                  ErasureTaskStatus status, int erasedCount, int remainingCount) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 记录写入请求：仅当前有效代次可写入。
 * 携带全局幂等 requestId 与非空操作者；期望版本用于声明客户端预期写入的代次，
 * 与当前有效代次不一致时返回 409，避免撤回重授权后误写新代。
 *
 * @param requestId     幂等请求标识
 * @param subjectKey    主体标识（合成字符串）
 * @param purpose       用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param recordKey     记录键，同一代内唯一
 * @param payload       记录内容（合成字符串），文本逐字节原样比对
 * @param operator      操作者标识（合成字符串），非空
 * @param expectedEpoch 期望写入的授权代次，从 1 开始
 */
public record RecordWriteRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull Purpose purpose,
        @NotBlank @Size(max = 128) String recordKey,
        @NotBlank @Size(max = 8192) String payload,
        @NotBlank @Size(max = 128) String operator,
        @NotNull @Min(1) Integer expectedEpoch) {
}

