@SpringBootTest
@AutoConfigureMockMvc
class ErasureApiTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private JdbcTemplate jdbc;

    @Autowired
    private ErasureService erasureService;

    @Autowired
